from collections import Counter, defaultdict
seq=''.join(l.strip() for l in open('region.fasta') if not l.startswith('>'))
n=len(seq)
# direct repeats length >= 12, allowing exact repeats
for L in [20,15,12]:
    d=defaultdict(list)
    for i in range(n-L+1):
        d[seq[i:i+L]].append(i)
    reps={k:v for k,v in d.items() if len(v)>1}
    print('exact repeat length',L,'count',len(reps))
    for k,v in list(reps.items())[:20]:
        print(' ',k,v)
    print()
# inverted repeats: find reverse complement matches length >= 12
comp=str.maketrans('ACGT','TGCA')
for L in [20,15,12]:
    arr=[]
    for i in range(n-L+1):
        a=seq[i:i+L]
        rc=a.translate(comp)[::-1]
        j=seq.find(rc)
        if j>=0 and j!=i and i<j:
            arr.append((i,j,a))
    print('inverted length',L,'count',len(arr))
    for x in arr[:20]: print(' ',x)
    print()

